import { event } from "@useamplio/amplio";
import { z } from "zod";
// amplio:plugin-imports

export const HttpRequest = event({
  id: "http.request",
  version: 1,
  schema: z.object({
    request_id: z.string(),
    http: z.object({
      method: z.string(),
      route: z.string().optional(),
      status: z.number().int().optional(),
    }),
  }),
  tree: {
    // amplio:plugins
  },
});

export function resolveRequestId(value: unknown): string {
  if (typeof value === "string" && /^[A-Za-z0-9_-]{1,128}$/.test(value)) {
    return value;
  }
  return crypto.randomUUID();
}

import "../runtime.js";

import type { Context, MiddlewareHandler, Next } from "hono";
import { HttpRequest, resolveRequestId } from "../events/http-request.js";

const handleRequest = HttpRequest.handle(
  async (context: Context, next: Next) => {
    await next();
  },
  {
    input: ({ args: [context] }) => ({
      request_id: resolveRequestId(context.req.header("x-request-id")),
      http: { method: context.req.method },
    }),
    result: ({ args: [context] }) => ({
      http: {
        route: context.req.routePath || undefined,
        status: context.res.status,
      },
    }),
    success: ({ args: [context] }) => context.res.status < 400,
    error: ({ args: [context] }) => ({
      http: {
        route: context.req.routePath || undefined,
      },
    }),
  },
);

/** Hono boundary Plugin: application handlers remain ordinary Hono handlers. */
export function HonoPlugin(): MiddlewareHandler {
  return handleRequest;
}

import "../runtime.js";

import { openEvent, type EventScope } from "@useamplio/amplio/plugin";
import type { ErrorRequestHandler, RequestHandler } from "express";
import { HttpRequest, resolveRequestId } from "../events/http-request.js";

interface PendingRequest {
  readonly scope: EventScope<typeof HttpRequest>;
  error?: unknown;
  settled: boolean;
}

/**
 * Put the boundary first by spreading every returned route layer.
 * All supplied middleware and the final response lifecycle stay in one Event.
 */
export function withAmplioRoute(
  route: string,
  ...handlers: RequestHandler[]
): Array<RequestHandler | ErrorRequestHandler> {
  const pending = new WeakMap<object, PendingRequest>();

  const boundary: RequestHandler = (request, response, next) => {
    const scope = openEvent(HttpRequest, {
      request_id: resolveRequestId(request.get("x-request-id")),
      http: { method: request.method, route },
    });
    const state: PendingRequest = { scope, settled: false };
    pending.set(request, state);

    const settle = (closedEarly: boolean) => {
      if (state.settled) return;
      state.settled = true;
      response.off("finish", onFinish);
      response.off("close", onClose);
      pending.delete(request);
      const output = {
        http: { route, status: response.statusCode },
      };
      if (state.error !== undefined) {
        scope.fail(state.error, output);
      } else if (closedEarly && !response.writableFinished) {
        scope.update(output);
        scope.cancel("response_closed");
      } else {
        scope.finish(output, { success: response.statusCode < 400 });
      }
    };
    const onFinish = scope.bind(() => settle(false));
    const onClose = scope.bind(() => settle(true));
    response.once("finish", onFinish);
    response.once("close", onClose);

    scope.run(() => {
      try {
        next();
      } catch (error) {
        state.error = error;
        next(error);
      }
    });
    if (response.writableFinished || response.destroyed) {
      settle(response.destroyed && !response.writableFinished);
    }
  };

  const captureError: ErrorRequestHandler = (
    error,
    request,
    _response,
    next,
  ) => {
    const state = pending.get(request);
    if (state && error !== "route" && error !== "router") {
      state.error = error;
    }
    next(error);
  };

  return [boundary, ...handlers, captureError];
}

import "../runtime.js";

import { openEvent, type EventScope } from "@useamplio/amplio/plugin";
import type { FastifyError, FastifyPluginAsync, FastifyRequest } from "fastify";
import { HttpRequest, resolveRequestId } from "../events/http-request.js";

interface PendingRequest {
  readonly scope: EventScope<typeof HttpRequest>;
  error?: FastifyError;
}

/** Register once before routes; ordinary Fastify handlers remain untouched. */
const implementation: FastifyPluginAsync = async (app) => {
  const pending = new WeakMap<FastifyRequest, PendingRequest>();

  app.addHook("onRequest", (request, _reply, done) => {
    const scope = openEvent(HttpRequest, {
      request_id: resolveRequestId(request.headers["x-request-id"]),
      http: { method: request.method },
    });
    pending.set(request, { scope });
    scope.run(done);
  });

  app.addHook("onError", (request, _reply, error, done) => {
    const state = pending.get(request);
    if (state) state.error = error;
    done();
  });

  app.addHook("onResponse", (request, reply, done) => {
    const state = pending.get(request);
    pending.delete(request);
    if (state) {
      const output = {
        http: {
          route: request.routeOptions.url,
          status: reply.statusCode,
        },
      };
      if (state.error) state.scope.fail(state.error, output);
      else {
        state.scope.finish(output, { success: reply.statusCode < 400 });
      }
    }
    done();
  });

  app.addHook("onRequestAbort", (request, done) => {
    const state = pending.get(request);
    pending.delete(request);
    if (state) {
      state.scope.update({
        http: { route: request.routeOptions.url },
      });
      state.scope.cancel("request_aborted");
    }
    done();
  });
};

// Fastify uses this documented symbol to expose lifecycle hooks outside the
// registration scope, which is exactly what a composition-root Plugin needs.
Object.defineProperties(implementation, {
  [Symbol.for("skip-override")]: { value: true },
  [Symbol.for("fastify.display-name")]: { value: "amplio-fastify" },
});

export const FastifyPlugin = implementation;

import "../runtime.js";

import type { NextRequest } from "next/server";
import { HttpRequest, resolveRequestId } from "../events/http-request.js";

type NextHandler = (
  request: NextRequest,
  ...args: any[]
) => Response | Promise<Response>;

export function withAmplio<F extends NextHandler>(
  route: string,
  handler: F,
): F {
  return HttpRequest.handle(handler, {
    input: ({ args: [request] }) => ({
      request_id: resolveRequestId(request.headers.get("x-request-id")),
      http: {
        method: request.method,
        route,
      },
    }),
    result: ({ result }) => ({
      http: { status: result.status },
    }),
    success: ({ result }) => result.status < 400,
  });
}

import { event } from "@useamplio/amplio";
import { plugin } from "@useamplio/amplio/plugin";
import { z } from "zod";

type TrpcProcedureType = "query" | "mutation" | "subscription";
type TrpcFailure = { ok: false; error: unknown };

const TrpcProcedure = event({
  id: "trpc.procedure",
  version: 1,
  schema: z.object({
    path: z.string(),
    type: z.enum(["query", "mutation"]),
  }),
  timing: "duration",
  cardinality: { many: { max: 64 } },
});

function isFailure(value: unknown): value is TrpcFailure {
  try {
    return (
      typeof value === "object" &&
      value !== null &&
      "ok" in value &&
      value.ok === false &&
      "error" in value
    );
  } catch {
    return false;
  }
}

export const TrpcPlugin = plugin({
  id: "trpc",
  events: { procedures: TrpcProcedure },
  instrument({ events, begin }) {
    return function trpcMiddleware() {
      return <Result>(options: {
        path: string;
        type: TrpcProcedureType;
        next: () => Promise<Result>;
      }): Promise<Result> => {
        // The middleware promise only represents subscription setup, not the
        // stream's lifetime. Preserve it exactly rather than claiming false
        // duration or completion semantics.
        if (options.type === "subscription") return options.next();

        const observation = begin(events.procedures, {
          path: options.path,
          type: options.type,
        });
        return observation.run(async () => {
          try {
            const result = await options.next();
            if (isFailure(result)) observation.fail(result.error);
            else observation.end();
            return result;
          } catch (error) {
            observation.fail(error);
            throw error;
          }
        });
      };
    };
  },
});

import { event } from "@useamplio/amplio";
import { plugin } from "@useamplio/amplio/plugin";
import type { BetterAuthPlugin as NativeBetterAuthPlugin } from "better-auth";
import { createAuthMiddleware } from "better-auth/api";
import { z } from "zod";

const AuthSession = {
  mfa: z.boolean().optional(),
  user: z.object({ id: z.string() }),
};

const SignedInResult = z.object({
  method: z.enum(["password", "oauth", "magic_link", "sso"]),
  ...AuthSession,
});

const SignedUpResult = z.object({
  method: z.enum(["email", "oauth", "invite"]),
  ...AuthSession,
});

type SignInMethod = z.infer<typeof SignedInResult>["method"];
type SignUpMethod = z.infer<typeof SignedUpResult>["method"];
type NativeAfterHook = NonNullable<
  NonNullable<NativeBetterAuthPlugin["hooks"]>["after"]
>[number];
type MatcherContext = Parameters<NativeAfterHook["matcher"]>[0];
type MiddlewareContext = Parameters<
  Parameters<typeof createAuthMiddleware>[0]
>[0];

function pathOf(context: MatcherContext): string {
  return typeof context.path === "string" ? context.path : "";
}

function hasConfirmedSession(context: MatcherContext): boolean {
  const id = context.context?.newSession?.user.id;
  return typeof id === "string" && id.length > 0;
}

function isRegistration(context: MatcherContext): boolean {
  const returned = context.context?.returned;
  if (returned === null || typeof returned !== "object") {
    return false;
  }

  try {
    return (returned as { isRegister?: unknown }).isRegister === true;
  } catch {
    return false;
  }
}

function isOAuthCallback(context: MatcherContext): boolean {
  const path = pathOf(context);
  return path.startsWith("/callback/") || path.startsWith("/oauth2/callback/");
}

function isEmailSignUp(context: MatcherContext): boolean {
  return pathOf(context) === "/sign-up/email" && hasConfirmedSession(context);
}

function isOAuthSignUp(context: MatcherContext): boolean {
  return (
    isOAuthCallback(context) &&
    hasConfirmedSession(context) &&
    isRegistration(context)
  );
}

function isInvitationSignUp(context: MatcherContext): boolean {
  const path = pathOf(context);
  return (
    (path === "/organization/signup-with-invitation" ||
      path.endsWith("/signup-with-invitation")) &&
    hasConfirmedSession(context)
  );
}

function isPasswordSignIn(context: MatcherContext): boolean {
  return (
    ["/sign-in/email", "/sign-in/username", "/sign-in/phone-number"].includes(
      pathOf(context),
    ) && hasConfirmedSession(context)
  );
}

function isOAuthSignIn(context: MatcherContext): boolean {
  return (
    isOAuthCallback(context) &&
    hasConfirmedSession(context) &&
    !isRegistration(context)
  );
}

function isMagicLinkSignIn(context: MatcherContext): boolean {
  return (
    pathOf(context) === "/magic-link/verify" && hasConfirmedSession(context)
  );
}

function isSsoSignIn(context: MatcherContext): boolean {
  const path = pathOf(context);
  return (
    (path === "/sign-in/sso" ||
      path.startsWith("/sso/callback") ||
      path.startsWith("/sso/saml2/")) &&
    hasConfirmedSession(context)
  );
}

function isMfaSignIn(context: MatcherContext): boolean {
  return (
    [
      "/two-factor/verify-totp",
      "/two-factor/verify-otp",
      "/two-factor/verify-backup-code",
    ].includes(pathOf(context)) && hasConfirmedSession(context)
  );
}

function projectSession(context: MiddlewareContext, forceMfa = false) {
  const session = context.context.newSession;
  if (!session?.user.id) {
    return;
  }

  const configuredMfa = session.user.twoFactorEnabled;
  const mfa = forceMfa
    ? true
    : typeof configuredMfa === "boolean"
      ? configuredMfa
      : undefined;

  return {
    user: { id: session.user.id },
    ...(mfa === undefined ? {} : { mfa }),
  };
}

export const BetterAuthPlugin = plugin({
  id: "better-auth",
  events: {
    signed_in: event({
      id: "auth.signed_in",
      version: 1,
      schema: SignedInResult,
      timing: "instant",
      cardinality: "single",
    }),
    signed_up: event({
      id: "auth.signed_up",
      version: 1,
      schema: SignedUpResult,
      timing: "instant",
      cardinality: "single",
    }),
  },
  instrument({ events, record }) {
    const recordSignedIn = (
      method: SignInMethod,
      context: MiddlewareContext,
      forceMfa = false,
    ): void => {
      const session = projectSession(context, forceMfa);
      if (!session) {
        return;
      }
      record(events.signed_in, { method, ...session });
    };

    const recordSignedUp = (
      method: SignUpMethod,
      context: MiddlewareContext,
    ): void => {
      const session = projectSession(context);
      if (!session) {
        return;
      }
      record(events.signed_up, { method, ...session });
    };

    return function createBetterAuthAdapter(): NativeBetterAuthPlugin {
      return {
        id: "amplio",
        hooks: {
          after: [
            {
              matcher: isEmailSignUp,
              handler: createAuthMiddleware(async (context) => {
                recordSignedUp("email", context);
              }),
            },
            {
              matcher: isInvitationSignUp,
              handler: createAuthMiddleware(async (context) => {
                recordSignedUp("invite", context);
              }),
            },
            {
              matcher: isOAuthSignUp,
              handler: createAuthMiddleware(async (context) => {
                recordSignedUp("oauth", context);
              }),
            },
            {
              matcher: isPasswordSignIn,
              handler: createAuthMiddleware(async (context) => {
                recordSignedIn("password", context);
              }),
            },
            {
              matcher: isOAuthSignIn,
              handler: createAuthMiddleware(async (context) => {
                recordSignedIn("oauth", context);
              }),
            },
            {
              matcher: isMagicLinkSignIn,
              handler: createAuthMiddleware(async (context) => {
                recordSignedIn("magic_link", context);
              }),
            },
            {
              matcher: isSsoSignIn,
              handler: createAuthMiddleware(async (context) => {
                recordSignedIn("sso", context);
              }),
            },
            {
              matcher: isMfaSignIn,
              handler: createAuthMiddleware(async (context) => {
                recordSignedIn("password", context, true);
              }),
            },
          ],
        },
      };
    };
  },
});

import { event } from "@useamplio/amplio";
import { plugin } from "@useamplio/amplio/plugin";
import type { CreateEmailOptions, Resend } from "resend";
import { z } from "zod";

const ResendSend = event({
  id: "resend.send",
  version: 1,
  schema: z.object({
    provider: z.literal("resend"),
    template: z.string().optional(),
  }),
  timing: "duration",
  cardinality: { many: { max: 16 } },
});

const templateTag = (input: CreateEmailOptions): string | undefined =>
  input.tags?.find((tag) => tag.name === "template")?.value;

const instrumentedClients = new WeakSet<Resend>();

export const ResendPlugin = plugin({
  id: "resend",
  events: { sends: ResendSend },
  instrument({ events, observe }) {
    return <Client extends Resend>(client: Client): Client => {
      if (instrumentedClients.has(client)) {
        return client;
      }

      const send = client.emails.send.bind(client.emails);
      client.emails.send = observe(events.sends, send, {
        input: ({ args: [input] }) => {
          const template = templateTag(input);
          return {
            provider: "resend",
            ...(template ? { template } : {}),
          };
        },
        success: ({ result }) => result.error === null,
      });
      instrumentedClients.add(client);
      return client;
    };
  },
});

import { init } from "@useamplio/amplio";
import { consoleSink } from "./sinks/console.js";

init({
  service: process.env.SERVICE_NAME ?? "my-app",
  env: process.env.NODE_ENV ?? "development",
  enrichers: [],
  // sampling: { rate: 0.1, keep: [{ field: "success", equals: false }] },
  // see @useamplio/amplio README ## Sampling
  sinks: [consoleSink],
});

import type { Sink } from "@useamplio/amplio";

const createJsonReplacer = () => {
  const ancestors: object[] = [];
  return function (this: object, _key: string, value: unknown): unknown {
    if (typeof value === "bigint") {
      return value.toString();
    }
    if (value === null || typeof value !== "object") {
      return value;
    }
    while (ancestors.length > 0 && ancestors[ancestors.length - 1] !== this) {
      ancestors.pop();
    }
    if (ancestors.includes(value)) {
      return "[Circular]";
    }
    ancestors.push(value);
    return value;
  };
};

export const consoleSink: Sink = (record) => {
  console.log(JSON.stringify(record, createJsonReplacer()));
};

/**
 * Dev-grade JSONL sink — appendFileSync blocks the event loop.
 * Use sink-otlp for production. Path from AMPLIO_JSON_SINK_PATH env or option;
 * defaults to amplio.<env>.jsonl (e.g. amplio.development.jsonl) so dev rows
 * and build/production rows never interleave in one file. Add amplio*.jsonl
 * to .gitignore (amplio add sink json does this).
 */
import fs from "node:fs";
import path from "node:path";
import type { Sink, SinkRecord } from "@useamplio/amplio";

export interface JsonFileSinkOptions {
  path?: string;
}

export function jsonFileSink(options: JsonFileSinkOptions = {}): Sink {
  const explicitPath =
    options.path ?? (process.env.AMPLIO_JSON_SINK_PATH?.trim() || undefined);

  return (record: SinkRecord) => {
    const env = typeof record.env === "string" && record.env ? record.env : "dev";
    const filePath = explicitPath ?? `amplio.${env}.jsonl`;
    const dir = path.dirname(filePath);
    if (dir && dir !== ".") {
      fs.mkdirSync(dir, { recursive: true });
    }
    fs.appendFileSync(filePath, `${JSON.stringify(record)}\n`, "utf8");
  };
}

/**
 * OTLP/HTTP logs sink.
 *
 * Endpoint resolution (first match wins):
 *   1. options.endpoint                          — `/v1/logs` appended unless already present
 *   2. OTEL_EXPORTER_OTLP_LOGS_ENDPOINT          — used VERBATIM (per the OTel spec,
 *      signal-specific endpoints are full URLs)
 *   3. OTEL_EXPORTER_OTLP_ENDPOINT               — base URL, `/v1/logs` appended
 *
 * Delivery: by default this sink POSTs ONE request per emit — fine for dev
 * and low traffic, not for production request rates. Pass `batch: true`
 * (100 records / 1 s) or `batch: { maxSize, maxWaitMs }` to coalesce records
 * into one export request. Batching makes the sink async-pending between
 * flushes. Amplio's `flush()` calls the sink's active drain hook, so shutdown
 * and short-lived/serverless paths can deliver a partial batch immediately.
 */
import type { JsonValue, Sink, SinkRecord } from "@useamplio/amplio";

export interface OtlpSinkOptions {
  endpoint?: string;
  headers?: Record<string, string>;
  /** When false (default), export failures warn once then stay silent. Pass true to throw. */
  throwOnError?: boolean;
  /**
   * Record fields promoted to typed OTLP log attributes (the fields you can
   * filter on in an OTel backend without parsing the JSON body). Dot paths
   * walk nested objects (`"http.status"` → record.http.status). Replaces the
   * default list; the full record always ships in the log body.
   */
  attributes?: string[];
  /**
   * Coalesce records into one export request. `true` = 100 records / 1 s;
   * pass `{ maxSize, maxWaitMs }` to tune. Default: off (one POST per emit).
   */
  batch?: boolean | { maxSize?: number; maxWaitMs?: number };
}

const DEFAULT_ATTRIBUTE_FIELDS = [
  "service",
  "@event",
  "duration_ms",
  "request_id",
  "success",
  // The fields people actually filter on in an OTel backend:
  "http.method",
  "http.route",
  "http.status",
  "rpc.procedures",
] as const;

const DEFAULT_BATCH_MAX_SIZE = 100;
const DEFAULT_BATCH_MAX_WAIT_MS = 1_000;

type OtlpAttributeValue =
  | { stringValue: string }
  | { boolValue: boolean }
  | { intValue: string }
  | { doubleValue: number }
  | { arrayValue: { values: OtlpAttributeValue[] } }
  | { kvlistValue: { values: OtlpAttribute[] } };

interface OtlpAttribute {
  key: string;
  value: OtlpAttributeValue;
}

const parseOtlpHeaders = (raw: string | undefined): Record<string, string> => {
  if (!raw) {
    return {};
  }

  const headers: Record<string, string> = {};
  for (const pair of raw.split(",")) {
    const trimmed = pair.trim();
    if (!trimmed) {
      continue;
    }

    const eq = trimmed.indexOf("=");
    if (eq === -1) {
      continue;
    }

    const key = trimmed.slice(0, eq).trim();
    const value = trimmed.slice(eq + 1).trim();
    if (key) {
      headers[key] = value;
    }
  }

  return headers;
};

/** Flat key first (`record["http.status"]`), then dot-path walk (`record.http.status`). */
const fieldValue = (
  record: SinkRecord,
  field: string,
): JsonValue | undefined => {
  if (field === "@event") {
    return record["@event"];
  }
  const flat = record[field];
  if (flat !== undefined || !field.includes(".")) {
    return flat;
  }
  let current: JsonValue | undefined = record as JsonValue;
  for (const part of field.split(".")) {
    if (
      current === null ||
      typeof current !== "object" ||
      Array.isArray(current)
    ) {
      return undefined;
    }
    current = (current as Record<string, JsonValue>)[part];
  }
  return current;
};

const toOtlpValue = (
  value: JsonValue | undefined,
): OtlpAttributeValue | undefined => {
  if (value === null || value === undefined) {
    return undefined;
  }

  if (typeof value === "string") {
    return { stringValue: value };
  }

  if (typeof value === "boolean") {
    return { boolValue: value };
  }

  if (typeof value === "number") {
    if (Number.isInteger(value)) {
      return { intValue: String(value) };
    }
    return { doubleValue: value };
  }

  if (Array.isArray(value)) {
    const values = value
      .map((item) => toOtlpValue(item))
      .filter((item): item is OtlpAttributeValue => item !== undefined);
    return { arrayValue: { values } };
  }

  const values = Object.entries(value)
    .map(([key, item]) => toOtlpAttribute(key, item))
    .filter((item): item is OtlpAttribute => item !== undefined);
  return { kvlistValue: { values } };
};

const toOtlpAttribute = (
  key: string,
  value: JsonValue | undefined,
): OtlpAttribute | undefined => {
  const converted = toOtlpValue(value);
  return converted ? { key, value: converted } : undefined;
};

const toTimeUnixNano = (timestamp: JsonValue | undefined): string => {
  let ms: number;

  if (typeof timestamp === "number" && Number.isFinite(timestamp)) {
    ms = timestamp;
  } else if (typeof timestamp === "string" && timestamp.length > 0) {
    const parsed = Date.parse(timestamp);
    ms = Number.isNaN(parsed) ? Date.now() : parsed;
  } else {
    ms = Date.now();
  }

  return `${Math.trunc(ms)}000000`;
};

const resolveUrl = (options: OtlpSinkOptions): string | undefined => {
  const appendLogsPath = (endpoint: string): string => {
    const base = endpoint.replace(/\/$/, "");
    return base.endsWith("/v1/logs") ? base : `${base}/v1/logs`;
  };

  if (options.endpoint) {
    return appendLogsPath(options.endpoint);
  }
  // Per the OTel spec the signal-specific endpoint is a full URL used as-is;
  // only the base endpoint gets the signal path appended.
  const signalEndpoint = process.env.OTEL_EXPORTER_OTLP_LOGS_ENDPOINT;
  if (signalEndpoint) {
    return signalEndpoint;
  }
  const baseEndpoint = process.env.OTEL_EXPORTER_OTLP_ENDPOINT;
  if (baseEndpoint) {
    return appendLogsPath(baseEndpoint);
  }
  return undefined;
};

const resourceKeyOf = (record: SinkRecord): string => {
  const attributes = buildResourceAttributes(record).sort((left, right) =>
    left.key.localeCompare(right.key),
  );
  return JSON.stringify(attributes);
};

const buildResourceAttributes = (record: SinkRecord): OtlpAttribute[] => {
  const attributes: OtlpAttribute[] = [];
  const keys = new Set<string>();
  const add = (attribute: OtlpAttribute | undefined): void => {
    if (!attribute || keys.has(attribute.key)) return;
    keys.add(attribute.key);
    attributes.push(attribute);
  };

  if (typeof record.service === "string" && record.service.length > 0) {
    add({ key: "service.name", value: { stringValue: record.service } });
  }
  if (typeof record.env === "string" && record.env.length > 0) {
    add({
      key: "deployment.environment",
      value: { stringValue: record.env },
    });
  }

  const resource = record.resource;
  if (
    resource !== null &&
    typeof resource === "object" &&
    !Array.isArray(resource)
  ) {
    for (const [key, value] of Object.entries(resource)) {
      add(toOtlpAttribute(key, value));
    }
  }

  return attributes;
};

export function otlpSink(options: OtlpSinkOptions = {}): Sink {
  const url = resolveUrl(options);
  const throwOnError = options.throwOnError ?? false;
  const attributeFields = options.attributes ?? DEFAULT_ATTRIBUTE_FIELDS;
  const headers = {
    "content-type": "application/json",
    ...parseOtlpHeaders(process.env.OTEL_EXPORTER_OTLP_HEADERS),
    ...(options.headers ?? {}),
  };

  if (!url) {
    let warned = false;
    return async () => {
      if (!warned) {
        warned = true;
        console.warn(
          "[amplio] otlpSink: no endpoint configured — set OTEL_EXPORTER_OTLP_LOGS_ENDPOINT (full URL, used verbatim) or OTEL_EXPORTER_OTLP_ENDPOINT (base URL, /v1/logs appended), or pass otlpSink({ endpoint }); OTLP export is disabled",
        );
      }
    };
  }

  let warnedExportFailure = false;

  const warnExportFailure = (detail: string): void => {
    if (throwOnError || warnedExportFailure) {
      return;
    }
    warnedExportFailure = true;
    console.warn(
      `[amplio] otlpSink: export failed (${detail}); further failures will be silent. Pass throwOnError: true to fail hard.`,
    );
  };

  const buildAttributes = (record: SinkRecord): OtlpAttribute[] => {
    const attributes: OtlpAttribute[] = [];
    for (const field of attributeFields) {
      // Keep the conventional OTLP attribute key `event` while sourcing the
      // canonical semantic `@event` field by default.
      const key = field === "@event" ? "event" : field;
      const attr = toOtlpAttribute(key, fieldValue(record, field));
      if (attr) {
        attributes.push(attr);
      }
    }
    return attributes;
  };

  const toLogRecord = (record: SinkRecord) => {
    const attributes = buildAttributes(record);
    return {
      timeUnixNano: toTimeUnixNano(record.timestamp),
      body: { stringValue: JSON.stringify(record) },
      ...(attributes.length > 0 ? { attributes } : {}),
    };
  };

  // One resourceLogs entry per distinct OTLP resource — records in a batch
  // usually share one, but never stamp record A with B's resource attributes.
  const buildPayload = (records: SinkRecord[]) => {
    const groups = new Map<string, SinkRecord[]>();
    for (const record of records) {
      const key = resourceKeyOf(record);
      const group = groups.get(key);
      if (group) {
        group.push(record);
      } else {
        groups.set(key, [record]);
      }
    }

    const resourceLogs = [...groups.values()].map((group) => {
      const first = group[0]!;
      const resourceAttributes = buildResourceAttributes(first);
      return {
        ...(resourceAttributes.length > 0
          ? { resource: { attributes: resourceAttributes } }
          : {}),
        scopeLogs: [{ logRecords: group.map(toLogRecord) }],
      };
    });

    return { resourceLogs };
  };

  const exportRecords = async (records: SinkRecord[]): Promise<void> => {
    let response: Response;
    try {
      response = await fetch(url, {
        method: "POST",
        headers,
        body: JSON.stringify(buildPayload(records)),
      });
    } catch (error) {
      if (throwOnError) {
        throw error;
      }
      warnExportFailure("network_error");
      return;
    }

    if (!response.ok) {
      if (throwOnError) {
        throw new Error(`OTLP export failed with status ${response.status}`);
      }
      warnExportFailure(`status ${response.status}`);
      return;
    }
  };

  if (!options.batch) {
    return (record: SinkRecord) => exportRecords([record]);
  }

  const batchConfig = options.batch === true ? {} : options.batch;
  const maxSize = batchConfig.maxSize ?? DEFAULT_BATCH_MAX_SIZE;
  const maxWaitMs = batchConfig.maxWaitMs ?? DEFAULT_BATCH_MAX_WAIT_MS;

  let buffer: SinkRecord[] = [];
  let timer: ReturnType<typeof setTimeout> | null = null;
  let pending: {
    promise: Promise<void>;
    resolve: () => void;
    reject: (e: unknown) => void;
  } | null = null;

  const flushBatch = (): Promise<void> => {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
    const records = buffer;
    const settled = pending;
    buffer = [];
    pending = null;
    if (records.length === 0) {
      settled?.resolve();
      return Promise.resolve();
    }
    const delivery = exportRecords(records).then(
      () => settled?.resolve(),
      (error) => {
        // Every emit in the batch awaited this promise — reject them all so
        // throwOnError surfaces per-record, matching the unbatched contract.
        if (settled) {
          settled.reject(error);
        }
      },
    );
    return delivery;
  };

  const sink: Sink = (record: SinkRecord): Promise<void> => {
    buffer.push(record);
    if (pending === null) {
      let resolve!: () => void;
      let reject!: (e: unknown) => void;
      const promise = new Promise<void>((res, rej) => {
        resolve = res;
        reject = rej;
      });
      pending = { promise, resolve, reject };
    }
    const result = pending.promise;
    if (buffer.length >= maxSize) {
      void flushBatch();
    } else if (timer === null) {
      timer = setTimeout(flushBatch, maxWaitMs);
      // Don't keep a Node process alive just for a pending batch window.
      (timer as { unref?: () => void }).unref?.();
    }
    return result;
  };
  sink.flush = flushBatch;
  return sink;
}

type ResourceAttributes = Readonly<Record<string, string | number | boolean>>;
type ResourceEnricher = (
  current: ResourceAttributes,
) => ResourceAttributes | undefined;

function envOrUndefined(key: string): string | undefined {
  const value = process.env[key]?.trim();
  return value ? value : undefined;
}

/** Adds bounded operational attributes under `record.resource`. */
export const serviceMetadata: ResourceEnricher = (
  current: ResourceAttributes,
) => ({
  ...current,
  ...(envOrUndefined("AMPLIO_SERVICE")
    ? { "deployment.name": envOrUndefined("AMPLIO_SERVICE")! }
    : {}),
  ...(envOrUndefined("AMPLIO_SERVICE_VERSION")
    ? { "deployment.version": envOrUndefined("AMPLIO_SERVICE_VERSION")! }
    : {}),
  ...(envOrUndefined("AMPLIO_REGION")
    ? { "deployment.region": envOrUndefined("AMPLIO_REGION")! }
    : {}),
});
